const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    var pt = ee.Geometry.Point([-116.5453, 33.8303]);
    var region = pt.buffer(5000); // 5 km buffer around Palm Springs center

    var start2017 = ee.Date('2017-07-15');
    var end2017 = start2017.advance(7, 'day'); // exclusive end: Jul 22

    var baseStartYear = 2001;
    var baseEndYear = 2010;

    // 2. Helpers
    function maskLST(img) {
      var qc = img.select('QC_Day');
      var mandatory = qc.bitwiseAnd(3); // bits 0-1
      var good = mandatory.eq(0);
      var lstC = img.select('LST_Day_1km').multiply(0.02).subtract(273.15); // Kelvin->C
      return lstC.updateMask(good).rename('LST');
    }

    function combinedMaskedCol(start, end, geom) {
      var terra = ee.ImageCollection('MODIS/061/MOD11A1').filterDate(start, end).filterBounds(geom).map(maskLST);
      var aqua  = ee.ImageCollection('MODIS/061/MYD11A1').filterDate(start, end).filterBounds(geom).map(maskLST);
      return terra.merge(aqua);
    }

    function periodStats(start, end, geom) {
      var col = combinedMaskedCol(start, end, geom);
      var imgs = col.size();
      var ones = ee.Image(1);
      var totalPix = ones.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geom,
        scale: 1000,
        maxPixels: 1e9
      }).get('constant');

      // Build true/false branches lazily
      var weekly = col.mean().rename('LST');
      var validPix = weekly.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geom,
        scale: 1000,
        maxPixels: 1e9
      }).get('LST');
      var meanC = weekly.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: geom,
        scale: 1000,
        maxPixels: 1e9
      }).get('LST');

      var dictTrue = ee.Dictionary({
        imgs: imgs,
        totalPix: totalPix,
        validPix: validPix,
        validPct: ee.Number(validPix).divide(ee.Number(totalPix)).multiply(100),
        meanC: meanC
      });
      var dictFalse = ee.Dictionary({
        imgs: imgs,
        totalPix: totalPix,
        validPix: 0,
        validPct: 0,
        meanC: null
      });
      return ee.Dictionary(ee.Algorithms.If(imgs.gt(0), dictTrue, dictFalse));
    }

    function baselineStats(geom) {
      var years = ee.List.sequence(baseStartYear, baseEndYear);
      var feats = ee.FeatureCollection(years.map(function(y) {
        y = ee.Number(y);
        var s = ee.Date.fromYMD(y, 7, 15);
        var e = s.advance(7, 'day');
        var d = periodStats(s, e, geom);
        d = ee.Dictionary(d).set('year', y);
        return ee.Feature(null, d);
      }));

      var totalImgs = ee.Number(feats.aggregate_sum('imgs'));
      var used = feats.filter(ee.Filter.gt('validPix', 0)).filter(ee.Filter.notNull(['meanC']));
      var yearsUsed = used.size();
      var baselineMean = ee.Number(used.aggregate_mean('meanC'));
      var validPctAvg = ee.Number(used.aggregate_mean('validPct'));
      return ee.Dictionary({
        totalImgs: totalImgs,
        yearsUsed: yearsUsed,
        baselineMeanC: baselineMean,
        validPctAvg: validPctAvg
      });
    }

    // 3. Compute stats
    var stats2017 = periodStats(start2017, end2017, region);
    var baseStats = baselineStats(region);

    // 4. Bring results client-side
    function getInfoAsync(obj) {
      return new Promise((resolve, reject) => obj.getInfo(resolve, reject));
    }
    var res = await getInfoAsync(ee.Dictionary({
      y2017: stats2017,
      base: baseStats
    }));

    // 5. Validation & Final Answer
    var y2017 = res.y2017 || {};
    var base = res.base || {};

    var imgs2017 = y2017.imgs || 0;
    var totalPix2017 = y2017.totalPix || 0;
    var validPix2017 = y2017.validPix === null ? 0 : (y2017.validPix || 0);
    var validPct2017 = y2017.validPct === null ? 0 : (y2017.validPct || 0);
    var mean2017 = (typeof y2017.meanC === 'number') ? y2017.meanC : null;

    var baseImgs = base.totalImgs || 0;
    var yearsUsed = base.yearsUsed || 0;
    var baseMean = (typeof base.baselineMeanC === 'number') ? base.baselineMeanC : null;
    var baseValidPctAvg = (typeof base.validPctAvg === 'number') ? base.validPctAvg : null;

    // Print concise evidence (<= 20 lines)
    console.log(`2017 imgs: ${imgs2017}, valid px: ${validPix2017}/${totalPix2017} (${validPct2017 ? validPct2017.toFixed(1) : '0.0'}%), mean C: ${mean2017 !== null ? mean2017.toFixed(2) : 'null'}`);
    console.log(`2001-2010 yrs used: ${yearsUsed}/10, imgs: ${baseImgs}, valid% avg: ${baseValidPctAvg !== null ? baseValidPctAvg.toFixed(1) : 'null'}%, mean C: ${baseMean !== null ? baseMean.toFixed(2) : 'null'}`);

    // Determine outcome tag
    // Case C1: No images for one or both comparison points
    if (imgs2017 === 0 || baseImgs === 0) {
      console.log('C1');
      return;
    }
    // Case C2: No valid pixels after masking
    if (validPix2017 === 0 || yearsUsed === 0) {
      console.log('C2');
      return;
    }
    // Case C3: Calculation failure (null/NaN or implausible values)
    function badVal(v) {
      return v === null || !isFinite(v) || v < -80 || v > 80;
    }
    if (badVal(mean2017) || badVal(baseMean)) {
      console.log('C3');
      return;
    }

    var diff = mean2017 - baseMean;
    console.log(`Diff (2017 - baseline): ${diff.toFixed(2)} C`);

    if (diff > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
